input.value:
timeseries used = avg(jvm.memory.used), from: now() - 1h, by:{service.name, jvm.memory.type}
| fieldsAdd latest = arrayLast(used)
| sort latest desc

timeseries util = avg(nodejs.eventloop.utilization), delay_p99 = avg(nodejs.eventloop.delay.p99), from: now() - 1h, by:{service.name}
| fieldsAdd latest_util = arrayLast(util)
| sort latest_util desc

fetch spans, from: now() - 30m
| filter telemetry.distro.name == "opentelemetry-ebpf-instrumentation" and k8s.namespace.name == "otel-demo"
| summarize spans = count(), services = countDistinct(service.name), by:{trace.id}
| summarize traces = count(), avg_spans = avg(spans), by:{services}
| sort services asc
